{
  "current_version": "10.4",
  "releases": [
    {
      "date": "November 9, 2026",
      "version": "10.4",
      "url": "https://core.telegram.org/bots/api-changelog#november-9-2026",
      "changes": [
        {
          "text": "Added the class Widget and the field widget to the classes Message and ExternalReplyInfo for messages with HTML widgets.",
          "topic": "Widgets",
          "refs": [
            "ExternalReplyInfo",
            "Message",
            "Widget"
          ],
          "terms": [
            "widget"
          ]
        },
        {
          "text": "Added the method sendWidget, allowing bots to send messages with HTML widgets. Currently, in the production environment, widgets can be sent only to private chats, and sent widgets automatically have protected content and therefore can't be forwarded.",
          "topic": "Widgets",
          "refs": [
            "sendWidget"
          ],
          "terms": []
        },
        {
          "text": "Added the method sendSharedWidget, allowing bots to send again shared widgets created by the bot.",
          "topic": "Widgets",
          "refs": [
            "sendSharedWidget"
          ],
          "terms": []
        },
        {
          "text": "Added the class WidgetQuery and the field widget_query to the class Update for queries sent to the bot by widgets in messages sent by the bot or via the bot.",
          "topic": "Widgets",
          "refs": [
            "Update",
            "WidgetQuery"
          ],
          "terms": [
            "widget_query"
          ]
        },
        {
          "text": "Added the class SharedWidgetQuery and the field shared_widget_query to the class Update for queries sent to the bot from forwarded messages with shared widgets.",
          "topic": "Widgets",
          "refs": [
            "SharedWidgetQuery",
            "Update"
          ],
          "terms": [
            "shared_widget_query"
          ]
        },
        {
          "text": "Added the classes WidgetQueryType, WidgetQueryTypeData, WidgetQueryTypeSignData, WidgetQueryTypeSentTransaction and WidgetQueryWallet, describing the type of a query from a widget. A query can contain data for the bot together with the TON wallet card of the user, data signed by a TON wallet of the user, or a notification about a transaction sent from a TON wallet of the user.",
          "topic": "Widgets",
          "refs": [
            "WidgetQueryType",
            "WidgetQueryTypeData",
            "WidgetQueryTypeSentTransaction",
            "WidgetQueryTypeSignData",
            "WidgetQueryWallet"
          ],
          "terms": []
        },
        {
          "text": "Added the method answerWidgetQuery, allowing bots to answer queries from widgets.",
          "topic": "Widgets",
          "refs": [
            "answerWidgetQuery"
          ],
          "terms": []
        },
        {
          "text": "Added the method editMessageWidgetData, allowing bots to change data of a widget in a message.",
          "topic": "Widgets",
          "refs": [
            "editMessageWidgetData"
          ],
          "terms": []
        },
        {
          "text": "Added the method editSharedWidgetData, allowing bots to change public data of a shared widget.",
          "topic": "Widgets",
          "refs": [
            "editSharedWidgetData"
          ],
          "terms": []
        },
        {
          "text": "Added the classes InputWidgetMessageContent and InputSharedWidgetMessageContent, allowing bots to send widgets in response to inline queries. Currently, widgets can't be sent in response to inline queries in the production environment.",
          "topic": "Widgets",
          "refs": [
            "InputSharedWidgetMessageContent",
            "InputWidgetMessageContent"
          ],
          "terms": []
        },
        {
          "text": "Widget messages can't be copied using the methods copyMessage and copyMessages.",
          "topic": "Widgets",
          "refs": [
            "copyMessage",
            "copyMessages"
          ],
          "terms": []
        },
        {
          "text": "The right can_send_other_messages in the classes ChatPermissions and ChatMemberRestricted now also allows sending widgets.",
          "topic": "Widgets",
          "refs": [
            "ChatMemberRestricted",
            "ChatPermissions"
          ],
          "terms": [
            "can_send_other_messages"
          ]
        },
        {
          "text": "Allowed bots to send ephemeral replies to callback queries in any chat except channel direct messages chats by specifying callback_query_id without receiver_user_id in the parameter ephemeral_message_parameters of the methods sendMessage, sendRichMessage, sendAnimation, sendAudio, sendContact, sendDocument, sendLivePhoto, sendLocation, sendPhoto, sendSticker, sendVenue, sendVideo, sendVideoNote and sendVoice.",
          "topic": "Ephemeral messages",
          "refs": [
            "sendAnimation",
            "sendAudio",
            "sendContact",
            "sendDocument",
            "sendLivePhoto",
            "sendLocation",
            "sendMessage",
            "sendPhoto",
            "sendRichMessage",
            "sendSticker",
            "sendVenue",
            "sendVideo",
            "sendVideoNote",
            "sendVoice"
          ],
          "terms": [
            "callback_query_id",
            "ephemeral_message_parameters",
            "receiver_user_id"
          ]
        },
        {
          "text": "The field receiver_user_id of the class EphemeralMessageParameters and the parameter chat_id of the mentioned methods are optional now.",
          "topic": "Ephemeral messages",
          "refs": [
            "EphemeralMessageParameters"
          ],
          "terms": [
            "chat_id",
            "receiver_user_id"
          ]
        },
        {
          "text": "Added the field rich_texts to the class TextQuote for quotes chosen from a RichMessage.",
          "topic": "Quotes from rich messages",
          "refs": [
            "RichMessage",
            "TextQuote"
          ],
          "terms": [
            "rich_texts"
          ]
        },
        {
          "text": "Added the field quote_rich_texts to the class ReplyParameters, allowing bots to quote rich messages.",
          "topic": "Quotes from rich messages",
          "refs": [
            "ReplyParameters"
          ],
          "terms": [
            "quote_rich_texts"
          ]
        },
        {
          "text": "Added the classes TonWalletCard, TonWalletCardSticker, TonNft and TonNftAttribute, and the field ton_wallet_card to the class ChatFullInfo.",
          "topic": "TON wallet",
          "refs": [
            "ChatFullInfo",
            "TonNft",
            "TonNftAttribute",
            "TonWalletCard",
            "TonWalletCardSticker"
          ],
          "terms": [
            "ton_wallet_card"
          ]
        },
        {
          "text": "Added the class TonWalletTransfer and the field ton_wallet_transfer to the class Message for service messages about transfers with a TON wallet.",
          "topic": "TON wallet",
          "refs": [
            "Message",
            "TonWalletTransfer"
          ],
          "terms": [
            "ton_wallet_transfer"
          ]
        },
        {
          "text": "Renamed the class StoryAreaPosition to AreaPosition, because it is now also used to describe the position of stickers on TON wallet cards.",
          "topic": "TON wallet",
          "refs": [
            "AreaPosition"
          ],
          "terms": []
        },
        {
          "text": "Added the classes ChatShareTheme, ChatShareThemeEmoji and ChatShareThemeUniqueGift, and the field share_theme to the class ChatFullInfo, describing the theme of the screen for sharing a link to a user or a chat.",
          "topic": "Chat share themes",
          "refs": [
            "ChatFullInfo",
            "ChatShareTheme",
            "ChatShareThemeEmoji",
            "ChatShareThemeUniqueGift"
          ],
          "terms": [
            "share_theme"
          ]
        },
        {
          "text": "Added the classes EmojiType, EmojiTypeEmoji and EmojiTypeCustomEmoji.",
          "topic": "Chat share themes",
          "refs": [
            "EmojiType",
            "EmojiTypeCustomEmoji",
            "EmojiTypeEmoji"
          ],
          "terms": []
        },
        {
          "text": "Added the classes ChatShareThemeBackdrop and ChatShareThemeBackdrops and the method getChatShareThemeBackdrops.",
          "topic": "Chat share themes",
          "refs": [
            "ChatShareThemeBackdrop",
            "ChatShareThemeBackdrops",
            "getChatShareThemeBackdrops"
          ],
          "terms": []
        },
        {
          "text": "Added the method getUniqueGift, allowing bots to get information about a unique gift by its name.",
          "topic": "Gifts",
          "refs": [
            "getUniqueGift"
          ],
          "terms": []
        },
        {
          "text": "Added the method deleteBusinessAccountGift, allowing bots to delete regular gifts owned by a managed business account without receiving Telegram Stars for them.",
          "topic": "Gifts",
          "refs": [
            "deleteBusinessAccountGift"
          ],
          "terms": []
        },
        {
          "text": "Allowed users with a Telegram Premium subscription to assign secondary usernames ending with “agent”, “ai”, “app”, “game”, or “gay” to up to 2 owned bots. Such usernames can be suggested in the field suggested_username of the class KeyboardButtonRequestManagedBot.",
          "topic": "General",
          "refs": [
            "KeyboardButtonRequestManagedBot"
          ],
          "terms": [
            "suggested_username"
          ]
        },
        {
          "text": "Added the class RichTextTonAddress representing an address in the TON blockchain in a RichMessage.",
          "topic": "General",
          "refs": [
            "RichMessage",
            "RichTextTonAddress"
          ],
          "terms": []
        },
        {
          "text": "Added the type “ton_address” to the class MessageEntity for addresses in the TON blockchain.",
          "topic": "General",
          "refs": [
            "MessageEntity"
          ],
          "terms": []
        },
        {
          "text": "Added the type “bank_card_number” to the class MessageEntity for bank card numbers.",
          "topic": "General",
          "refs": [
            "MessageEntity"
          ],
          "terms": []
        },
        {
          "text": "Added the parameters custom_description_parse_mode and custom_description_entities to the methods verifyUser and verifyChat.",
          "topic": "General",
          "refs": [
            "verifyChat",
            "verifyUser"
          ],
          "terms": [
            "custom_description_entities",
            "custom_description_parse_mode"
          ]
        },
        {
          "text": "Added the class PaidMessagesWaived and the field paid_messages_waived to the class Message for service messages about the sender using a link which allows sending messages without paying Telegram Stars.",
          "topic": "General",
          "refs": [
            "Message",
            "PaidMessagesWaived"
          ],
          "terms": [
            "paid_messages_waived"
          ]
        },
        {
          "text": "Added the ability to create links to topics in private chats with the bot in the format `https://t.me/<bot_username>/<message_thread_id>`. Such a link opens the topic only for the user in the private chat with whom the topic exists.",
          "topic": "General",
          "refs": [],
          "terms": []
        }
      ]
    },
